//learn from: https://www.shadertoy.com/view/3sySRK

let mySize;

// a shader variable
let theShader;
let shaderTexture;

let theta = 0;

function preload() {
	theShader = createShader(vert, frag)
}

function setup() {
	 // pixelDensity(1);
	// mySize = max(windowWidth, windowHeight);
	mySize = 600;
	// shaders require WEBGL mode to work
	createCanvas(mySize, mySize, WEBGL);
	noStroke();
	shaderTexture = createGraphics(width, height, WEBGL);
	shaderTexture.noStroke();
}

function draw() {  
  // shader() sets the active shader with our shader
  shader(theShader);

  theShader.setUniform("u_resolution", [width*2, height*2]);
  theShader.setUniform("u_time", frameCount * 0.01);
  theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/1000.0, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)/1000.0]);

  // rect gives us some geometry on the screen
  rect(0,0,width, height);
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
}

function keyPressed() {
	//noLoop();
	saveCanvas("0627_Shaders_011_2022", "png");
}

// === Tab: frag ===
//noprotect
const frag = `

#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;

float opSmoothUnion( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.05, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}

float sdSphere( vec3 p, float s )
{
  return length(p)-fract(s)-s/1.0;
} 

float map(vec3 p)
{
	float d = 24.0;
	for (int i = 0; i < 6; i++) {
		float fi = float(i);
		float time = u_time * (fract(fi * 1.531 - 0.513) - 0.45) * 2.0;
		d = opSmoothUnion(
            sdSphere(p + sin(time + fi * vec3(2.5126, 64.62744, 632.25)) * vec3(2.0, 2.0, 0.8), mix(0.5, 1.0, fract(fi * 2.531 + 0.5124))),
			d,
			0.99
		);
	}
	return d;
}

vec3 calcNormal( in vec3 p )
{
    const float h = 1e-2; // or some other value
    const vec2 k = vec2(1,-1);
    return normalize( k.xyy*map( p + k.xyy*h ) + 
                      k.yyx*map( p + k.yyx*h ) + 
                      k.yxy*map( p + k.yxy*h ) + 
                      k.xxx*map( p + k.xxx*h ) );
}

void main(){
    vec2 uv = gl_FragCoord.xy/u_resolution.xy;

    // screen size is 6m x 6m
	vec3 rayOri = vec3((uv - 0.5) * vec2(u_resolution.x/u_resolution.y, u_resolution.y/u_resolution.x) * 12.0, 4.0);
	vec3 rayDir = vec3(0.0, 0.0, -1.0);

	float depth = 1.0*u_mouse.x;
	vec3 p;

	for(int i = 0; i < 32; i++) {
		p = rayOri + rayDir * depth;
		float dist = map(p);
        depth += dist;
		if (dist < 1e-2) {
			break;
		}
	}

    depth = min(6.0, depth);
	vec3 n = calcNormal(p);
    float b = max(0.0, dot(n, vec3(0.277)));
    vec3 col = (0.5 + 0.5 * cos((b + u_time * 3.0) + uv.xyx * 2.0 + vec3(0,2,4))) * (0.85 + b * 0.35);
    col *= exp( -depth * 0.15 );

    // maximum thickness is 2m in alpha channel
    gl_FragColor = vec4(col, 1.0 - (depth - 0.15) / 2.0);
}


`

// === Tab: vert ===
const vert = `
// vert file and comments from adam ferriss
// https://github.com/aferriss/p5jsShaderExamples

// our vertex data
attribute vec3 aPosition;

// our texcoordinates
attribute vec2 aTexCoord;

void main() {

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}
`;

